/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) === null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) === null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (loadTp === '2') {
        if (uploadCode === '0') {
            if (isOk === 'true') {
                await $c.win.alert('저장되었습니다.');
            } else {
                await $c.win.alert('저장시 오류가 발생하였습니다.\n첨부파일 정상 등록 여부를 확인하시기 바랍니다.');
            }
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    await $c.win.alert('저장시 오류가 발생하였습니다.');
                }
            }
        }
    }
};

/**
 * @method
 * @name setEditMode
 * @description set Edit Mode 처리
 * @param {*} tp tp
 * @returns {void}
 * @hidden N
 */
scwin.setEditMode = function (tp) {

    let div;
    let files;
    const chkObj = document.getElementsByName('useYn');
    const editObj = document.getElementsByName('editYn');
    const itmObj = document.getElementsByName('fileItmNm');
    const remkObj = document.getElementsByName('remk');
    if(tp === 0 || tp === 1){
        for(let i = 0;i<chkObj.length;i++){
            div = $c.util.getComponent("div_edit"+i);
            editObj[i].checked = true;
            div.style.visibility = "hidden";
        }
    }else{
        for(let i = 0;i<chkObj.length;i++){
            files = form['attachFiles['+i+']'];
            files.disabled = true;
            chkObj[i].disabled = true;
            itmObj[i].readOnly = true;
            remkObj[i].readOnly = true;
        }
    }
    if(tp === 0){
        ($c.util.getComponent("div_edit_title_1") && $c.util.getComponent("div_edit_title_1").setValue) ? $c.util.getComponent("div_edit_title_1").setValue("-") : (($c.util.getComponent("div_edit_title_1") && $c.util.getComponent("div_edit_title_1").setText) ? $c.util.getComponent("div_edit_title_1").setText("-") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "div_edit_title_1"), void ("-")));
        ($c.util.getComponent("div_edit_title_2") && $c.util.getComponent("div_edit_title_2").setValue) ? $c.util.getComponent("div_edit_title_2").setValue("-") : (($c.util.getComponent("div_edit_title_2") && $c.util.getComponent("div_edit_title_2").setText) ? $c.util.getComponent("div_edit_title_2").setText("-") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "div_edit_title_2"), void ("-")));
        for(let i = "${fn:length(formFileList)}";i<chkObj.length;i++){
            files = form['attachFiles['+i+']'];
            files.disabled = true;
            itmObj[i].readOnly = true;
            chkObj[i].checked = true;
        }
    }else{
        ($c.util.getComponent("div_edit_title_1") && $c.util.getComponent("div_edit_title_1").setValue) ? $c.util.getComponent("div_edit_title_1").setValue("수정") : (($c.util.getComponent("div_edit_title_1") && $c.util.getComponent("div_edit_title_1").setText) ? $c.util.getComponent("div_edit_title_1").setText("수정") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "div_edit_title_1"), void ("수정")));
        ($c.util.getComponent("div_edit_title_2") && $c.util.getComponent("div_edit_title_2").setValue) ? $c.util.getComponent("div_edit_title_2").setValue("수정") : (($c.util.getComponent("div_edit_title_2") && $c.util.getComponent("div_edit_title_2").setText) ? $c.util.getComponent("div_edit_title_2").setText("수정") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "div_edit_title_2"), void ("수정")));
    }

};

/**
 * @method
 * @name editAttach
 * @description edit Attach 처리
 * @param {*} inputTagObj inputTagObj
 * @returns {void}
 * @hidden N
 */
scwin.editAttach = function (inputTagObj) {
    const itemId = $(inputTagObj).attr("itemId");
    const itemObj = $("#" + itemId).get(0);
    const objIdx = Number(itemId.replace("docuItem", ""));
    if ($(itemObj).find("input[name='editYn']").is(":checked")) {
        $(itemObj).find("input[name='useYn']").removeAttr("disabled");
        $(itemObj).find("input[name='remk']").removeAttr("readonly");
        if ($(itemObj).find("input[name='useYn']").is(":checked")) {
            $(itemObj).find("#attachFiles" + objIdx).attr("disabled", true);
            if (objIdx >= $) {
                fn: length(formFileList);
            }
            $(itemObj).find("input[name='fileItmNm']").attr("readonly", true);
        } else {
            $(itemObj).find("#attachFiles" + objIdx).removeAttr("disabled");
            if (objIdx >= $) {
                fn: length(formFileList);
            }
            $(itemObj).find("input[name='fileItmNm']").removeAttr("readonly");
        }
    } else {
        $(itemObj).find("input[name='useYn']").attr("disabled", true);
        $(itemObj).find("input[name='remk']").attr("readonly", true);
        $(itemObj).find("#attachFiles" + objIdx).attr("disabled", true);
    }
};

