        }
        $(itemObj).find("input[name='fileItmNm']").removeAttr("readonly");
    }
};

/**
 * @method
 * @name getObjIdx
 * @description get Obj Idx 처리
 * @param {*} tmpObj tmpObj
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.getObjIdx = function (tmpObj, ver) {
    let idx;
    const chkObj = document.getElementsByName(ver);
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i] === '[object]') {
            if (chkObj[i] === tmpObj) {
                idx = i;
                break;
            }
        }
    }
    return idx;
};

